WITH filtered AS (SELECT *, UPPER(brand) AS brand_upper, COALESCE(brand, 'NONE') AS brand_filled FROM products WHERE brand IS NOT NULL AND stock_qty = 327) SELECT *, ROW_NUMBER() OVER (ORDER BY stock_qty ASC, id ASC) AS row_seq, ROW_NUMBER() OVER (PARTITION BY brand ORDER BY launch_date DESC, id ASC) AS event_seq, AVG(stock_qty) OVER (PARTITION BY brand ORDER BY price ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS stock_qty_avg_2 FROM filtered;
